/* Step-by-step recipes, keyed by meal id. */
const HOWTO = {
  /* ---------- Breakfast ---------- */
  'moimoi-egg': {time:'1 hr 30 min + overnight soak', serves:'6',
    ing:['2 1/2 cups dried black-eyed peas or honey beans','6 eggs','3 tatashe (or red bell peppers)','1 large onion','1 scotch bonnet pepper','1/3 cup vegetable oil or palm oil','2 tbsp ground crayfish','1 stock cube','1 tsp salt','1 1/2 cups warm water'],
    steps:['The night before, soak the beans in plenty of water for 10 minutes, then rub them between your hands so the skins float off. Rinse away the skins, cover with fresh water and refrigerate overnight.',
      'Boil the eggs for 10 minutes, cool them in cold water and peel. Cut each egg into quarters.',
      'Drain the beans and blend with the tatashe, onion, scotch bonnet and warm water until completely smooth.',
      'Pour into a large bowl. Stir in the oil, crayfish, crushed stock cube and salt until the batter is an even orange color.',
      'Grease 6 to 8 ramekins or foil cups and fill each two-thirds full. Push a piece of egg into each one.',
      'Set a rack in a large pot with 2 inches of simmering water. Stand the cups on it, cover tightly and steam for 45 to 60 minutes, adding hot water if the pot runs low.',
      'Test one with a knife: it should come out clean and the moi moi should feel firm. Rest 10 minutes, then turn out and serve with the remaining egg pieces.']},

  'egg-plantain': {time:'30 min', serves:'2',
    ing:['2 unripe (green) plantains','3 eggs','2 medium tomatoes, chopped','1/2 medium onion, sliced','1/2 scotch bonnet pepper, finely chopped','1 tbsp vegetable oil','1/4 tsp salt','4 cups water for boiling'],
    steps:['Cut the ends off the plantains, slit the skin along the length and cut each one in half.',
      'Boil the plantains in their skins in the salted water for 20 minutes, until a fork slides in. Peel while warm.',
      'While they boil, heat the oil in a skillet and fry the onion for 2 minutes.',
      'Add the tomatoes and scotch bonnet and cook for 6 to 8 minutes until the tomatoes break down and the sauce thickens.',
      'Beat the eggs with a pinch of salt, pour into the sauce and stir gently for 2 to 3 minutes until fully set.',
      'Serve one finger of plantain per person with a generous spoon of egg sauce. No more than one finger for Daddy.']},

  'veg-omelette': {time:'15 min', serves:'2',
    ing:['4 eggs','2 cups fresh spinach or ugu, chopped','1/2 small onion, finely chopped','1 tatashe (or 1/2 red bell pepper), finely chopped','2 tsp vegetable oil','1 ripe avocado','1/4 tsp salt','1/4 tsp black pepper'],
    steps:['Heat 1 teaspoon of oil in a nonstick skillet over medium heat. Fry the onion and tatashe for 2 minutes.',
      'Add the spinach or ugu and stir for 1 to 2 minutes until wilted. Tip the vegetables into a bowl.',
      'Beat the eggs with the salt and black pepper, then stir in the cooked vegetables.',
      'Add the remaining oil to the pan and pour in half the egg mixture. Cook for 2 minutes, then fold over and cook 1 more minute until set.',
      'Slide onto a plate and repeat with the rest of the egg mixture.',
      'Halve the avocado, slice it and serve half beside each omelette.']},

  'okpa': {time:'1 hr', serves:'2',
    ing:['3/4 cup okpa (Bambara nut) flour','3 tbsp palm oil','1 cup warm water','1/2 scotch bonnet pepper, finely chopped','1/2 tsp salt','2 garden eggs, to serve'],
    steps:['Put the okpa flour in a bowl and stir in the palm oil, rubbing out any lumps with a spoon. The flour should turn yellow all over.',
      'Add the warm water a little at a time, whisking until you have a smooth, pourable batter.',
      'Stir in the salt and scotch bonnet.',
      'Grease 4 small ramekins or foil cups and fill them with the batter. Cover each with foil.',
      'Stand them on a rack in a pot with 2 inches of simmering water. Cover and steam for 45 minutes, topping up with hot water as needed.',
      'It is done when firm and a knife comes out clean. Serve warm with sliced garden egg, one or two small cups each.']},

  'oats-nuts': {time:'15 min', serves:'2',
    ing:['1 cup rolled oats','1 cup water','1 cup unsweetened milk','1/4 cup unsalted roasted groundnuts, lightly crushed','1/2 tsp ground cinnamon','1 pinch salt'],
    steps:['Bring the water and milk to a gentle simmer in a small pot.',
      'Stir in the oats and salt.',
      'Cook on low for 5 to 7 minutes, stirring often, until thick and creamy.',
      'Take off the heat and stir in the cinnamon. Do not add sugar.',
      'Divide between two bowls and top each with the crushed groundnuts.']},

  'akara-pap': {time:'50 min + overnight soak', serves:'6',
    ing:['2 cups dried black-eyed peas or honey beans','1 large onion, half chopped and half diced small','1 scotch bonnet pepper','3/4 tsp salt','1/4 cup water for blending','3 cups vegetable oil for frying','1 1/2 cups pap (ogi) paste','1/2 cup cold water for the pap','5 cups boiling water','1 cup evaporated milk','6 tsp sugar (optional, for the kids)'],
    steps:['The night before, soak the beans for 10 minutes, rub off the skins, rinse them away, then cover with fresh water and refrigerate overnight.',
      'Drain the beans and blend with the chopped onion, scotch bonnet and 1/4 cup water until very smooth. Use as little water as you can so the batter stays thick.',
      'Pour into a large bowl and whisk hard for 3 to 4 minutes until light and fluffy. Stir in the salt and the diced onion just before frying.',
      'Heat the oil in a deep pot to 350°F. Drop in spoonfuls of batter, a few at a time, and fry for 2 to 3 minutes on each side until deep golden and cooked through.',
      'Lift out onto paper towels. Check the first akara by breaking it open: the middle should be fully cooked, not wet.',
      'For the pap, loosen the ogi paste with the cold water in a large bowl until smooth.',
      'Pour in the boiling water in a steady stream, stirring fast, until it thickens and turns glossy. If it stays thin, heat it in a pot for 2 minutes while stirring.',
      'Stir in the milk and sugar if using, and serve hot with the akara. Daddy skips the pap.']},

  'yam-egg': {time:'40 min', serves:'6',
    ing:['1 medium tuber of yam (about 3 lb)','8 eggs','4 medium tomatoes, chopped','1 large onion, sliced','1 scotch bonnet pepper, finely chopped','1/4 cup vegetable oil','1 tsp salt','8 cups water for boiling'],
    steps:['Cut the yam into 1-inch rounds, peel them and cut each round in half. Rinse well.',
      'Boil in the water with 1/2 teaspoon salt for 15 to 20 minutes, until a fork slides in easily. Drain.',
      'Meanwhile heat the oil in a large skillet and fry the onion for 3 minutes.',
      'Add the tomatoes and scotch bonnet and cook for 8 to 10 minutes until thick and no longer sharp.',
      'Beat the eggs with the remaining salt and pour them in. Stir gently for 3 minutes until fully set.',
      'Serve the hot yam with the egg sauce on top. Daddy has 2 small slices at most.']},

  'bread-egg': {time:'15 min', serves:'4',
    ing:['8 slices bread','6 eggs','3 tbsp butter','1/4 tsp salt','1/4 tsp black pepper'],
    steps:['Toast the bread if the kids like it crisp, or leave it soft.',
      'Crack the eggs into a bowl, add the salt and pepper and beat lightly if you want them scrambled style, or fry them whole.',
      'Melt 1 tablespoon of butter in a skillet over medium heat.',
      'Fry the eggs in batches for 2 to 3 minutes until the whites and yolks are firm, adding more butter for each batch.',
      'Butter the bread with what is left, lay the eggs on four slices and top with the other four.',
      'Cut in half and serve warm, or cool fully and wrap for the lunchbox.']},

  'custard': {time:'45 min + overnight soak', serves:'4',
    ing:['1/2 cup custard powder','1/4 cup cold water','3 cups boiling water','1/2 cup evaporated milk','2 tbsp sugar','1 1/2 cups dried black-eyed peas or honey beans','1 medium onion, half chopped and half diced small','3 tbsp water for blending','1/2 tsp salt','2 1/2 cups vegetable oil for frying'],
    steps:['The night before, soak the beans for 10 minutes, rub off the skins, rinse them away, then cover with fresh water and refrigerate overnight.',
      'Drain the beans and blend with the chopped onion and 3 tablespoons of water until very smooth.',
      'Whisk the batter in a bowl for 3 minutes until fluffy, then stir in the salt and diced onion.',
      'Heat the oil to 350°F. Fry spoonfuls for 2 to 3 minutes on each side until deep golden and cooked through, then drain on paper towels.',
      'For the custard, mix the custard powder with the cold water in a large heatproof bowl until smooth.',
      'Pour in the boiling water in a steady stream, stirring all the time, until it thickens and turns a deep yellow.',
      'Stir in the milk and sugar and serve warm with the akara.']},

  'indomie-egg': {time:'15 min', serves:'4',
    ing:['4 packs instant noodles (keep 2 seasoning sachets)','4 eggs','2 medium carrots, cut into thin sticks','1 cup green beans, finely sliced','1 small onion, sliced','2 tbsp vegetable oil','4 cups water'],
    steps:['Bring the water to a boil and cook the noodles for 2 minutes only, so they stay firm. Drain, keeping 1/4 cup of the water.',
      'Heat 1 tablespoon of oil in a large skillet and fry the onion for 1 minute.',
      'Add the carrots and green beans and stir-fry for 3 minutes until just tender.',
      'Add the noodles, the saved water and 2 seasoning sachets. Toss for 2 minutes until the water is absorbed.',
      'In another pan, fry the eggs in the remaining oil for 2 to 3 minutes until firm.',
      'Serve the noodles with one egg on each plate. For the lunchbox, cool first and chop the egg through the noodles.']},

  'pancakes': {time:'30 min', serves:'4',
    ing:['1 1/2 cups all-purpose flour','2 eggs','1 3/4 cups milk','2 tbsp sugar','1/4 tsp salt','8 breakfast sausages','2 tbsp butter or vegetable oil for the pan'],
    steps:['Whisk the flour, sugar and salt in a bowl. Make a well in the middle and add the eggs and half the milk.',
      'Whisk until smooth, then stir in the rest of the milk. The batter should be thin, like heavy cream.',
      'Cook the sausages in a skillet over medium heat for 10 to 12 minutes, turning often, until brown and cooked through to 160°F.',
      'Wipe a nonstick pan with a little butter and heat over medium.',
      'Pour in a small ladle of batter and tilt the pan to spread it thin. Cook for 1 to 2 minutes each side until golden.',
      'Stack the pancakes on a plate and repeat until the batter is finished.',
      'Roll up the pancakes and serve with two sausages each. For the lunchbox, cool them before packing.']},

  'sweet-potato-egg': {time:'30 min', serves:'2',
    ing:['2 small sweet potatoes, scrubbed, skin on','3 eggs','2 medium tomatoes, chopped','1/2 medium onion, sliced','1/2 scotch bonnet pepper, finely chopped','1 tbsp vegetable oil','1/4 tsp salt','4 cups water for boiling'],
    steps:['Cut the sweet potatoes into thick rounds, leaving the skin on.',
      'Boil for 12 to 15 minutes until just tender, then drain. Do not fry them.',
      'Heat the oil in a skillet and fry the onion for 2 minutes.',
      'Add the tomatoes and scotch bonnet and cook for 6 to 8 minutes until thick.',
      'Beat the eggs with the salt, pour into the sauce and stir gently for 2 to 3 minutes until set.',
      'Serve a palm-size portion of sweet potato with plenty of egg sauce.']},

  /* ---------- Kids lunchbox ---------- */
  'jollof-chicken': {time:'1 hr 15 min', serves:'6',
    ing:['3 cups long-grain parboiled rice','3 lb chicken pieces','4 medium tomatoes','4 tatashe (or red bell peppers)','2 large onions','2 scotch bonnet peppers','1/3 cup vegetable oil','1/4 cup tomato paste','2 tsp curry powder','2 tsp dried thyme','2 stock cubes','2 bay leaves','1 1/2 tsp salt','4 cups water'],
    steps:['Put the chicken in a pot with one sliced onion, 1 teaspoon each of curry and thyme, 1 stock cube, 1/2 teaspoon salt and the water. Boil for 20 minutes, then save the stock.',
      'Lay the chicken on a tray and broil or bake at 425°F for 15 minutes until browned and 165°F in the thickest part.',
      'Blend the tomatoes, tatashe, the second onion and scotch bonnet until smooth. Boil in a pot for 10 minutes to reduce the water.',
      'Heat the oil in a heavy pot and fry the tomato paste for 3 minutes. Add the reduced pepper mix and fry for 10 to 12 minutes until the oil rises to the top.',
      'Stir in the remaining curry, thyme, stock cube, salt and the bay leaves, then pour in 3 cups of the chicken stock.',
      'Rinse the rice, stir it in and bring to a boil. The liquid should sit just level with the rice.',
      'Cover with foil and a tight lid and cook on the lowest heat for 30 minutes, stirring once halfway. Add a splash of stock only if the rice is still hard.',
      'Turn off the heat, leave covered for 5 minutes, then fluff with a fork. Remove the bay leaves and serve with the chicken.']},

  'fried-rice': {time:'1 hr 15 min', serves:'6',
    ing:['3 cups long-grain parboiled rice','2 lb chicken pieces','8 oz beef or chicken liver','2 medium carrots, diced small','1 cup green beans, finely sliced','1 cup sweetcorn','1 large onion, diced','1/3 cup vegetable oil, plus 2 cups for frying plantain','3 ripe plantains','2 tsp curry powder','1 tsp dried thyme','2 stock cubes','1 1/2 tsp salt','5 cups water'],
    steps:['Boil the chicken with half the onion, 1 stock cube, the thyme, 1/2 teaspoon salt and the water for 25 minutes. Lift out the chicken and save the stock.',
      'Bake the chicken at 425°F for 15 minutes until golden and 165°F in the thickest part.',
      'Boil the liver in a little of the stock for 10 minutes until cooked through, then dice it small.',
      'Rinse the rice and cook in 4 1/2 cups of stock with 1 teaspoon curry and the second stock cube for 15 minutes, until just tender and dry. Spread out on a tray to cool.',
      'Heat a little of the oil in a wide pan. Fry the rest of the onion with the carrots, green beans, sweetcorn and liver for 3 minutes with the remaining curry.',
      'Add the rice in batches with the rest of the oil, tossing over high heat for 3 to 4 minutes per batch until each grain is coated. Mix all batches together and salt to taste.',
      'Peel the plantains, slice them on an angle and fry in the 2 cups of oil for 2 to 3 minutes per side until golden brown.',
      'Serve the rice with chicken and dodo. Cool before packing a lunchbox and add an ice pack.']},

  'jollof-spag': {time:'50 min', serves:'6',
    ing:['1 1/2 lb spaghetti','3 medium mackerel (titus), cleaned and cut into steaks','4 medium tomatoes','3 tatashe (or red bell peppers)','2 medium onions','1 scotch bonnet pepper','1/3 cup vegetable oil','3 tbsp tomato paste','1 tsp curry powder','1 tsp dried thyme','2 stock cubes','1 1/2 tsp salt','3 cups water'],
    steps:['Put the fish in a pot with one sliced onion, 1 stock cube, 1/2 teaspoon salt and the water. Simmer for 10 minutes until the flesh flakes, then lift out gently and save the stock.',
      'Blend the tomatoes, tatashe, second onion and scotch bonnet until smooth.',
      'Heat the oil in a wide pot and fry the tomato paste for 2 minutes. Add the blended mix and fry for 12 to 15 minutes until thick and the oil rises.',
      'Stir in the curry, thyme, remaining stock cube and salt, and pour in 2 cups of the fish stock.',
      'Boil the spaghetti in a separate pot for 5 minutes only, then drain.',
      'Add the spaghetti to the sauce, toss well, cover and cook on low for 10 minutes until the sauce is absorbed and the pasta is soft.',
      'Serve with the mackerel on top. For the kids, take out the bones and flake the fish through the spaghetti.']},

  'meatpie': {time:'1 hr 30 min', serves:'4',
    ing:['4 cups all-purpose flour','1 cup (2 sticks) cold butter, cubed','1 tsp baking powder','1/2 tsp salt','1/2 cup cold water','1 lb minced beef','1 medium onion, diced','2 medium potatoes, diced small','2 medium carrots, diced small','1 tsp curry powder','1 tsp dried thyme','1 stock cube','2 tbsp flour mixed with 1/2 cup water','1 egg, beaten, for brushing','4 bananas'],
    steps:['Mix the flour, baking powder and salt in a bowl. Rub in the butter with your fingertips until it looks like breadcrumbs.',
      'Add the cold water a little at a time and press into a soft dough. Wrap and chill for 20 minutes.',
      'Brown the minced beef with the onion in a skillet for 6 to 8 minutes until no pink remains. Add the curry, thyme, stock cube, potatoes and carrots with 1/2 cup water.',
      'Cover and cook for 8 to 10 minutes until the potatoes are soft. Stir in the flour and water mix and cook 2 minutes until thick, then cool completely.',
      'Heat the oven to 350°F. Roll the dough 1/8 inch thick and cut 8 circles about 6 inches wide using a small plate.',
      'Put 2 tablespoons of filling on one half of each circle, brush the edge with egg, fold over and press with a fork to seal.',
      'Lay on a lined tray, brush with egg and bake for 35 to 40 minutes until golden.',
      'Cool on a rack, then pack one pie and one banana per lunchbox. Extra pies freeze well.']},

  'sandwich': {time:'30 min', serves:'4',
    ing:['8 slices bread','4 eggs','1 lb boneless chicken breast','4 lettuce leaves','1/4 cup mayonnaise','1/2 tsp curry powder','1/2 tsp salt','1/4 tsp black pepper','4 cups water'],
    steps:['Put the chicken in a pot with the water, curry and salt. Simmer for 15 to 18 minutes until 165°F in the thickest part, then cool and shred.',
      'Boil the eggs for 10 minutes, cool them in cold water, then peel and chop.',
      'Mix the chicken, eggs, mayonnaise and black pepper in a bowl.',
      'Wash the lettuce and pat it dry so the bread does not go soggy.',
      'Lay a lettuce leaf on four slices of bread, spread the filling on top and close with the other slices.',
      'Cut in half and wrap tightly. Keep in the fridge and pack with an ice pack, because of the mayonnaise.']},

  'plantain-beans': {time:'1 hr 45 min + overnight soak', serves:'6',
    ing:['3 cups dried black-eyed peas or honey beans','3 ripe plantains','1/3 cup palm oil','2 cups vegetable oil for frying plantain','1 large onion, sliced','1 scotch bonnet pepper, chopped','3 tbsp ground crayfish','1 stock cube','1 1/2 tsp salt','10 cups water'],
    steps:['The night before, cover the beans with plenty of water and soak. Drain and rinse them in the morning.',
      'Put the beans in a large pot with the water and boil hard for 10 minutes, then lower the heat and simmer for 50 to 60 minutes until very soft. Top up with hot water as needed.',
      'Heat the palm oil in a skillet and fry the onion and scotch bonnet for 3 to 4 minutes.',
      'Pour the onion and oil into the beans. Add the crayfish, stock cube and salt.',
      'Simmer for 15 minutes, stirring now and then, until thick. Mash some beans against the side of the pot to make it creamy.',
      'Peel the plantains and slice them on an angle. Fry in the vegetable oil for 2 to 3 minutes per side until golden brown, then drain.',
      'Serve the beans with the dodo on the side. Daddy has the beans and three small pieces of dodo at most.']},

  'yam-chips': {time:'50 min', serves:'4',
    ing:['1 1/2 lb yam','2 lb chicken drumsticks or thighs','3 cups vegetable oil for frying','1 tsp curry powder','1 tsp dried thyme','1 tsp paprika','1 stock cube, crushed','1 tsp salt','6 cups water'],
    steps:['Rub the chicken with the curry, thyme, paprika and crushed stock cube. Leave for 10 minutes while the oven heats to 425°F.',
      'Bake the chicken on a lined tray for 35 to 40 minutes, turning once, until golden and 165°F in the thickest part.',
      'Peel the yam and cut into thick chips. Rinse well.',
      'Boil the chips in the water with the salt for 5 minutes only, then drain and pat dry.',
      'Heat the oil to 350°F and fry the chips in batches for 5 to 6 minutes until golden and crisp.',
      'Drain on paper towels, and serve with the chicken. Cool before packing a lunchbox and add an ice pack.']},

  'puffpuff-snack': {time:'1 hr 15 min', serves:'4',
    ing:['3 cups all-purpose flour','2 1/4 tsp active dry yeast (1 packet)','1/2 cup sugar','1/2 tsp salt','1 1/2 cups warm water','4 cups vegetable oil for frying','4 small boxes of juice'],
    steps:['Stir the yeast and a pinch of the sugar into the warm water and leave for 5 minutes until foamy.',
      'Mix the flour, sugar and salt in a large bowl, then pour in the yeast water.',
      'Beat with a wooden spoon or your hand for 3 minutes into a thick, stretchy batter.',
      'Cover with a towel and leave somewhere warm for 45 minutes, until doubled and bubbly.',
      'Heat the oil in a deep pot to 350°F. Scoop up batter with a wet spoon and drop small balls gently into the oil.',
      'Fry for 3 to 4 minutes, turning them, until deep golden on every side. Fry only a few at a time.',
      'Drain on paper towels and cool. Pack a few with a box of juice as a treat.']},

  /* ---------- Daddy lunch pack ---------- */
  'beans-unripe': {time:'1 hr 45 min + overnight soak', serves:'6',
    ing:['3 cups dried black-eyed peas or honey beans','4 unripe (green) plantains, peeled and cut into chunks','1/3 cup palm oil','1 large onion, sliced','1 scotch bonnet pepper, chopped','3 tbsp ground crayfish','3 cups ugu leaves, chopped','1 stock cube','1 1/2 tsp salt','10 cups water'],
    steps:['The night before, cover the beans with plenty of water and soak. Drain and rinse them in the morning.',
      'Put the beans in a large pot with the water and boil hard for 10 minutes. Lower the heat and simmer for 45 minutes until nearly soft.',
      'Add the plantain chunks and cook for 15 minutes, until both are tender. Keep enough water in the pot to just cover.',
      'Heat the palm oil in a skillet and fry the onion and scotch bonnet for 3 to 4 minutes.',
      'Stir the onion and oil into the pot with the crayfish, stock cube and salt. Simmer for 10 minutes until thick.',
      'Stir in the ugu and cook for 2 minutes, just until it wilts.',
      'Serve hot. Daddy has about 1 1/2 cups; it packs well in a thermos for lunch.']},

  'fish-salad': {time:'35 min', serves:'2',
    ing:['2 small whole croaker or tilapia, cleaned','2 eggs','2 cups shredded cabbage','1 medium carrot, grated','1/2 cucumber, sliced','2 medium tomatoes, sliced','1 tbsp lemon juice','2 tbsp olive oil','1 tsp curry powder','1/2 tsp dried thyme','1/2 tsp salt','1/4 tsp black pepper'],
    steps:['Cut 3 slits on each side of the fish. Mix 1 tablespoon of the oil with the curry, thyme and salt, and rub it all over and into the slits.',
      'Heat the broiler or grill. Lay the fish on a lined tray and cook for 7 to 8 minutes on each side, until the flesh flakes and reaches 145°F.',
      'Boil the eggs for 10 minutes, cool them in cold water, then peel and quarter.',
      'Arrange the cabbage, carrot, cucumber and tomatoes on two plates.',
      'Whisk the lemon juice with the remaining oil and black pepper and drizzle it over the salad instead of salad cream.',
      'Top with the egg and serve with the hot fish.']},

  'chicken-veg': {time:'1 hr', serves:'6',
    ing:['3 lb chicken pieces','3 cups green beans, trimmed','3 medium carrots, cut into thin sticks','1/2 medium cabbage, shredded','4 tatashe (or red bell peppers)','2 large onions','2 scotch bonnet peppers','3 tbsp vegetable oil','1 tsp curry powder','1 tsp dried thyme','1 stock cube','1 tsp salt','4 cups water'],
    steps:['Boil the chicken with one sliced onion, the curry, thyme, stock cube, 1/2 teaspoon salt and the water for 20 minutes.',
      'Lift the chicken onto a tray and broil for 10 to 12 minutes, turning once, until browned and 165°F in the thickest part. Save 1/2 cup of the stock.',
      'Blend 3 tatashe, half of the second onion and the scotch bonnets until coarse.',
      'Heat 2 tablespoons of oil in a wide pan and fry the pepper mix for 10 minutes until thick. Add the saved stock and the chicken and toss for 3 minutes.',
      'Slice the remaining tatashe and onion. Heat the last tablespoon of oil in a hot skillet and stir-fry them with the carrots and green beans for 3 minutes.',
      'Add the cabbage and remaining salt and stir-fry for 2 more minutes, so the vegetables stay crisp.',
      'Serve the peppered chicken on a big bed of vegetables.']},

  'cauli-fried': {time:'35 min', serves:'2',
    ing:['1 medium head cauliflower','2 boneless chicken thighs, diced','4 oz chicken liver, diced','1 medium carrot, diced small','1/2 cup green beans, finely sliced','1 small onion, diced','2 tbsp vegetable oil','1 tsp curry powder','1/2 tsp dried thyme','1/2 stock cube, crushed','1/4 tsp salt'],
    steps:['Cut the cauliflower into florets and pulse in a food processor until it looks like rice, or grate it on a box grater.',
      'Heat 1 tablespoon of oil in a wide skillet. Fry the chicken with the thyme and half the curry for 6 to 8 minutes until golden and 165°F.',
      'Add the liver and cook for 4 minutes, stirring, until no pink remains. Tip everything onto a plate.',
      'Add the remaining oil to the pan and fry the onion, carrot and green beans for 3 minutes.',
      'Add the cauliflower, remaining curry, stock cube and salt. Stir-fry on high for 4 to 5 minutes until tender but not mushy.',
      'Return the chicken and liver to the pan, toss together for 1 minute and serve.']},

  'ofada-small': {time:'1 hr 15 min', serves:'2',
    ing:['1/2 cup ofada rice','1 cup water for the rice','3 green bell peppers','1 green scotch bonnet pepper','1 small onion, plus 1/4 onion sliced','1/4 cup palm oil','1 tbsp iru (locust beans)','8 oz assorted meat (beef, shaki, ponmo)','2 eggs','1/2 stock cube','1/2 tsp salt','3 cups water for the meat'],
    steps:['Boil the assorted meat in the 3 cups water with the stock cube and salt for 40 to 50 minutes until tender. Save 1/4 cup of the stock.',
      'Boil the eggs for 10 minutes, cool them in cold water and peel.',
      'Wash the ofada rice in several changes of water, then cook in the 1 cup water, covered, on low for 25 to 30 minutes until tender.',
      'Blend the green peppers, scotch bonnet and small onion until coarse. Simmer in a dry pot for 8 to 10 minutes to cook off the water.',
      'With a window open and the fan on, heat the palm oil in a covered pot on medium for 6 to 8 minutes until it lightens and starts to smoke. Stay by the pot, then take it off the heat and cool for 5 minutes.',
      'Return to low heat and fry the sliced onion and iru for 2 minutes. Add the pepper mix and fry for 12 to 15 minutes until the sauce darkens and the oil rises.',
      'Add the meat, saved stock and eggs, and simmer for 5 minutes.',
      'Serve 4 spoons of ofada per person with the ayamase on top.']},

  'brown-jollof': {time:'1 hr 30 min', serves:'6',
    ing:['2 1/2 cups long-grain brown rice','3 lb turkey pieces (wings or thighs)','4 medium tomatoes','3 tatashe (or red bell peppers)','2 large onions','1 scotch bonnet pepper','3 cups frozen mixed vegetables','1/4 cup vegetable oil','3 tbsp tomato paste','2 tsp curry powder','1 tsp dried thyme','2 stock cubes','1 tsp salt','6 cups water'],
    steps:['Boil the turkey with one sliced onion, 1 stock cube, 1 teaspoon curry, the thyme and the water for 30 minutes. Save the stock.',
      'Bake the turkey at 425°F for 15 to 20 minutes until browned and 165°F in the thickest part.',
      'Blend the tomatoes, tatashe, second onion and scotch bonnet. Boil in a pot for 10 minutes to reduce.',
      'Heat the oil in a heavy pot, fry the tomato paste for 2 minutes, then add the pepper mix and fry for 10 minutes until the oil rises.',
      'Add the remaining curry, stock cube, salt and 4 1/2 cups of stock. Rinse the brown rice and stir it in.',
      'Bring to a boil, cover with foil and a tight lid, and cook on low for 45 minutes, until the rice is tender. Add a splash of stock if it dries out early.',
      'Stir in the mixed vegetables, cover and leave for 5 minutes off the heat.',
      'Serve with the turkey. Daddy takes a fist-size scoop of rice and fills half the plate with vegetables.']},

  'moimoi-salad': {time:'1 hr 20 min + overnight soak', serves:'2',
    ing:['1 cup dried black-eyed peas or honey beans','2 eggs','1 tatashe (or 1/2 red bell pepper)','1/2 medium onion','1/2 scotch bonnet pepper','2 tbsp vegetable oil','1 tbsp ground crayfish','1/2 stock cube','1/2 cup warm water','2 cups shredded cabbage','1/2 cucumber, sliced','1 medium carrot, grated','1 tbsp lemon juice','1 tbsp olive oil','1/4 tsp salt'],
    steps:['The night before, soak the beans for 10 minutes, rub off the skins, rinse them away, then cover with fresh water and refrigerate overnight.',
      'Boil the eggs for 10 minutes, cool them in cold water, peel and quarter.',
      'Drain the beans and blend with the tatashe, onion, scotch bonnet and warm water until smooth.',
      'Stir in the vegetable oil, crayfish, stock cube and salt. Pour into 4 greased ramekins and add a piece of egg to each.',
      'Stand them on a rack in a pot with 2 inches of simmering water. Cover and steam for 40 to 45 minutes until firm and a knife comes out clean.',
      'Toss the cabbage, cucumber and carrot with the lemon juice and olive oil.',
      'Serve one or two moi moi per person with a large helping of salad. Keep spare moi moi in the fridge for up to 3 days.']},

  'gizdodo-lite': {time:'45 min', serves:'2',
    ing:['12 oz chicken gizzards, cleaned','6 garden eggs','2 tatashe (or 1 red bell pepper)','1 medium onion','1 scotch bonnet pepper','1 tbsp vegetable oil','1/2 tsp dried thyme','1/2 stock cube','1/4 tsp salt','3 cups water'],
    steps:['Boil the gizzards in the water with half the onion, the thyme, stock cube and salt for 25 to 30 minutes until tender and 165°F. Save 1/4 cup of the stock.',
      'Slice the gizzards thinly and sear them in a dry hot pan for 3 minutes until lightly browned.',
      'Blend the tatashe, scotch bonnet and remaining onion until coarse.',
      'Heat the oil in the pan and fry the pepper mix for 8 minutes until thick.',
      'Add the gizzards and saved stock, and simmer for 3 minutes until the sauce coats them.',
      'Wash the garden eggs, cut them in quarters and serve them raw alongside the gizzards.']},

  /* ---------- Family dinner ---------- */
  'efo-swallow': {time:'1 hr 30 min', serves:'6',
    ing:['2 lb fresh spinach (or frozen, thawed)','2 lb assorted meat (beef, shaki, ponmo)','4 oz stockfish pieces','5 tatashe (or red bell peppers)','2 large onions','2 scotch bonnet peppers','1/2 cup palm oil','2 tbsp iru (locust beans)','2 tbsp ground crayfish','2 stock cubes','1 tsp salt','6 cups water for the meat','3 cups poundo yam flour for the family swallow','5 cups water for the family swallow','1/3 cup oat flour for Daddy\'s swallow','2/3 cup water for Daddy\'s swallow'],
    steps:['Soak the stockfish in hot water for 30 minutes, then boil it with the meat, one sliced onion, the stock cubes, salt and the 6 cups water for 50 to 60 minutes until tender. Save 1 cup of the stock.',
      'Blend the tatashe, scotch bonnet and half the second onion until coarse. Simmer in a dry pot for 10 minutes to cook off the water.',
      'Chop the spinach, pour boiling water over it, drain, and squeeze out as much water as you can.',
      'Heat the palm oil in a wide pot. Slice the rest of the onion, fry it for 2 minutes, then add the iru and fry for 1 minute.',
      'Add the pepper mix and fry for 12 to 15 minutes until the oil rises to the top.',
      'Stir in the meat, stockfish, crayfish and saved stock, and simmer for 5 minutes.',
      'Fold in the spinach and cook for 3 to 4 minutes, uncovered, so it stays bright green.',
      'For the swallow, boil the 5 cups water, take it off the heat and stir in the poundo flour, then turn hard with a wooden spoon over low heat until smooth and stretchy. Add a splash of hot water, cover 2 minutes and turn again.',
      'For Daddy, boil the 2/3 cup water, stir in the oat flour and turn for 3 to 4 minutes until it holds together. Keep it fist-size, or he can skip swallow and have a double helping of efo.']},

  'egusi-swallow': {time:'1 hr 30 min', serves:'6',
    ing:['2 cups ground egusi','3 cups ugu or washed bitterleaf, chopped','2 lb assorted meat (beef, shaki, ponmo)','4 oz stockfish pieces','3 tbsp ground crayfish','1/2 cup palm oil','3 tatashe (or red bell peppers)','2 medium onions','2 scotch bonnet peppers','1 tbsp iru (locust beans)','2 stock cubes','1 tsp salt','7 cups water for the meat','3 cups elubo (yam flour) for the family amala','6 cups water for the family amala','1/3 cup oat flour for Daddy\'s swallow','2/3 cup water for Daddy\'s swallow'],
    steps:['Soak the stockfish in hot water for 30 minutes, then boil it with the meat, one sliced onion, the stock cubes, salt and the 7 cups water for 50 to 60 minutes until tender. Keep all the stock.',
      'Blend the tatashe, scotch bonnet and the second onion until smooth.',
      'Mix the ground egusi with 1/2 cup of water into a thick paste.',
      'Heat the palm oil in a wide pot. Fry the iru for 1 minute, add the blended pepper and fry for 10 minutes until it thickens.',
      'Drop in spoonfuls of the egusi paste. Cover and cook on low for 10 minutes without stirring, so the egusi forms soft lumps.',
      'Stir gently, then add the meat, stockfish, crayfish and 2 cups of stock. Simmer for 10 minutes.',
      'Add the ugu or bitterleaf and cook for 3 minutes.',
      'For the amala, bring the 6 cups water to a boil, sprinkle in the elubo and stir fast with a wooden spoon until smooth. Cover and steam on low for 2 minutes, then stir once more.',
      'For Daddy, boil the 2/3 cup water, stir in the oat flour and turn for 3 to 4 minutes until firm. Keep it a small wrap, with extra soup and meat.']},

  'okra-swallow': {time:'1 hr 15 min', serves:'6',
    ing:['1 1/2 lb fresh okra, finely chopped or grated','1 lb fresh or smoked fish, cut into pieces','1 1/2 lb assorted meat (beef, shaki, ponmo)','3 tbsp ground crayfish','2 cups ugu leaves, chopped','1/3 cup palm oil','1 scotch bonnet pepper, chopped','1 medium onion, sliced','2 stock cubes','1 tsp salt','6 cups water for the meat','3 cups garri for the family eba','5 cups water for the family eba','1/3 cup oat flour for Daddy\'s swallow','2/3 cup water for Daddy\'s swallow'],
    steps:['Boil the meat with the onion, stock cubes, salt and the 6 cups water for 45 to 50 minutes until tender.',
      'Add the fish and simmer for 8 minutes, until it flakes. There should be about 3 cups of stock left in the pot.',
      'Stir in the palm oil, crayfish and scotch bonnet and simmer for 5 minutes.',
      'Add the okra and cook on medium, uncovered, for 4 to 5 minutes. Do not overcook it, or it loses its stretch.',
      'Add the ugu, stir gently and cook for 2 more minutes, then turn off the heat.',
      'For the eba, boil the 5 cups water, take off the heat and sprinkle in the garri. Leave for 1 minute, then turn hard with a wooden spoon until smooth.',
      'For Daddy, boil the 2/3 cup water, stir in the oat flour and turn for 3 to 4 minutes until firm. Keep it small and let the okra do the work.']},

  'ogbono': {time:'1 hr 15 min', serves:'6',
    ing:['1 cup ground ogbono','2 lb assorted meat (beef, shaki, ponmo)','4 oz stockfish pieces','3 cups ugu leaves, chopped','1/3 cup palm oil','2 tbsp ground crayfish','1 scotch bonnet pepper, chopped','1 medium onion, sliced','2 stock cubes','1 tsp salt','7 cups water for the meat','3 cups semolina or wheat flour for the family swallow','6 cups water for the family swallow','1/3 cup oat flour for Daddy\'s swallow','2/3 cup water for Daddy\'s swallow'],
    steps:['Soak the stockfish in hot water for 30 minutes, then boil it with the meat, onion, stock cubes, salt and the 7 cups water for 50 to 60 minutes until tender. You want about 4 cups of stock left.',
      'Warm the palm oil in a separate pot over low heat, just until melted. Take it off the heat and stir in the ogbono until it dissolves into a smooth paste.',
      'Add 1 cup of stock to the ogbono and stir over low heat for 3 minutes until it starts to draw.',
      'Pour in the rest of the stock, the meat, stockfish, crayfish and scotch bonnet.',
      'Simmer on low for 10 to 12 minutes, stirring often so it does not stick. Add a little hot water if it gets too thick.',
      'Stir in the ugu and cook for 2 minutes.',
      'For the swallow, boil the 6 cups water and sprinkle in the semolina or wheat flour, stirring all the time. Cook on low for 5 minutes, turning hard, until smooth and firm.',
      'For Daddy, boil the 2/3 cup water, stir in the oat flour and turn for 3 to 4 minutes until firm. Keep it small.']},

  'edikaikong': {time:'1 hr 20 min', serves:'6',
    ing:['1 1/2 lb ugu leaves, chopped','1 lb waterleaf (or fresh spinach), chopped','1 cup cleaned periwinkle','2 lb assorted meat (beef, shaki, ponmo)','4 oz stockfish pieces','1/2 cup palm oil','3 tbsp ground crayfish','2 scotch bonnet peppers, chopped','1 large onion, sliced','2 stock cubes','1 tsp salt','5 cups water for the meat','3 cups poundo yam flour for the family swallow','5 cups water for the family swallow','1/3 cup oat flour for Daddy\'s swallow','2/3 cup water for Daddy\'s swallow'],
    steps:['Soak the stockfish in hot water for 30 minutes, then boil it with the meat, half the onion, the stock cubes, salt and the 5 cups water for 50 to 60 minutes until tender. Very little stock should remain, about 1 cup.',
      'Add the periwinkle, the rest of the onion, crayfish and scotch bonnet. Cook for 5 minutes.',
      'Pour in the palm oil and stir well. Simmer for 5 minutes.',
      'Add the waterleaf and cook for 4 minutes, as it releases its own water. Do not add more water.',
      'Add the ugu, stir well and cook for 3 to 4 minutes. The soup should be thick and the leaves still green.',
      'For the swallow, boil the 5 cups water, take it off the heat and stir in the poundo flour. Turn hard over low heat until smooth and stretchy.',
      'For Daddy, boil the 2/3 cup water, stir in the oat flour and turn for 3 to 4 minutes until firm. Keep it fist-size with plenty of soup.']},

  'banga': {time:'1 hr 15 min', serves:'6',
    ing:['1 can (28 oz) palm fruit concentrate','2 lb fresh fish (catfish or croaker), cut into pieces','1 piece smoked fish, cleaned','1 medium onion, chopped','2 scotch bonnet peppers, chopped','3 tbsp ground crayfish','1 tbsp beletete spice','1 stock cube','1 tsp salt','5 cups water','3 cups cassava starch for the swallow','1/4 cup palm oil for the swallow','6 cups water for the swallow'],
    steps:['Pour the palm fruit concentrate into a large pot with the 5 cups water. Stir and bring to a boil.',
      'Add the onion, scotch bonnet, crayfish and stock cube. Boil gently for 25 to 30 minutes, until the soup reduces and a little oil shows on top.',
      'Stir in the beletete spice and salt.',
      'Lay in the fresh fish and smoked fish. Simmer for 10 minutes without stirring, so the fish stays whole and reaches 145°F.',
      'For the starch, mix the cassava starch with 2 cups of the swallow water in a heavy pot until smooth. Stir in the palm oil.',
      'Add the remaining water and stir over medium heat for 6 to 8 minutes, until it turns glossy, stretchy and see-through.',
      'Shape into balls with wet hands and serve with the soup. Daddy has the soup and fish only.']},

  'stew-rice': {time:'1 hr 15 min', serves:'6',
    ing:['3 cups long-grain parboiled rice','3 lb chicken pieces or stewing beef','6 medium tomatoes','4 tatashe (or red bell peppers)','2 large onions','2 scotch bonnet peppers','1/2 cup vegetable oil','1/4 cup tomato paste','1 tsp curry powder','1 tsp dried thyme','2 stock cubes','2 tsp salt','10 cups water'],
    steps:['Boil the chicken or beef with one sliced onion, the curry, thyme, 1 stock cube, 1 teaspoon salt and 4 cups of the water. Allow 20 minutes for chicken or 45 minutes for beef, then save the stock.',
      'Brown the meat under the broiler for 10 minutes. Chicken must reach 165°F in the thickest part.',
      'Blend the tomatoes, tatashe, half the second onion and scotch bonnets. Boil in a pot for 15 minutes to reduce the water.',
      'Heat the oil in a heavy pot. Slice the rest of the onion, fry it for 3 minutes, then add the tomato paste and fry for 3 minutes.',
      'Pour in the pepper mix and fry for 15 minutes, stirring often, until the oil rises and it no longer tastes sharp.',
      'Add 1 cup of the stock, the remaining stock cube and the meat. Simmer for 10 minutes.',
      'Rinse the rice and boil in the remaining 6 cups of water with the remaining salt for 18 to 20 minutes until tender, then drain any extra water.',
      'Serve the rice with the stew on top. Daddy has 4 spoons of rice with extra stew and meat.']},

  'asaro': {time:'50 min', serves:'6',
    ing:['1 large tuber of yam (about 4 lb)','1/3 cup palm oil','3 tbsp ground crayfish','2 cups ugu leaves, chopped','2 tatashe (or red bell peppers)','2 scotch bonnet peppers','2 medium onions','1 stock cube','1 1/2 tsp salt','6 cups water'],
    steps:['Peel the yam, cut into 1-inch cubes and rinse well.',
      'Blend the tatashe, scotch bonnets and one onion until smooth. Slice the second onion.',
      'Put the yam in a large pot with the blended pepper, sliced onion, stock cube, salt and water. The water should just cover the yam.',
      'Boil for 20 minutes until the yam is very soft.',
      'Pour in the palm oil and crayfish. Mash about half the yam against the side of the pot with a wooden spoon, so the porridge turns thick and creamy.',
      'Simmer on low for 8 to 10 minutes, stirring now and then.',
      'Stir in the ugu, cook for 2 minutes and serve hot. Daddy has pepper soup instead tonight.']},

  'pepper-soup': {time:'1 hr 30 min', serves:'6',
    ing:['3 lb goat meat, cut into pieces (or 3 lb catfish steaks)','3 tbsp pepper soup spice','2 scotch bonnet peppers, chopped','1 large onion, chopped','1/4 cup uziza or scent leaf, sliced','2 tbsp ground crayfish','2 stock cubes','1 1/2 tsp salt','10 cups water'],
    steps:['Wash the goat meat and put it in a large pot with the onion, stock cubes, salt and 2 cups of the water. Steam on medium for 10 minutes to draw out the flavor.',
      'Add the rest of the water, the scotch bonnet, pepper soup spice and crayfish.',
      'Simmer for 1 hour, until the meat is tender. Top up with hot water if the level drops much.',
      'If using catfish instead, boil the seasoned broth for 15 minutes first, then add the fish and simmer for 10 minutes without stirring, until it flakes.',
      'Taste the broth and add salt or pepper if needed.',
      'Stir in the uziza or scent leaf, turn off the heat and cover for 2 minutes.',
      'Serve hot on its own. No carbs are needed for Daddy\'s bowl.']},

  'chicken-stew-plantain': {time:'1 hr 15 min', serves:'6',
    ing:['3 lb chicken pieces','6 medium tomatoes','4 tatashe (or red bell peppers)','6 unripe (green) plantains','2 large onions','2 scotch bonnet peppers','1/4 cup vegetable oil','3 tbsp tomato paste','1 tsp curry powder','1 tsp dried thyme','2 stock cubes','1 1/2 tsp salt','4 cups water for the chicken','8 cups water for the plantain'],
    steps:['Boil the chicken with one sliced onion, the curry, thyme, 1 stock cube, 1/2 teaspoon salt and 4 cups water for 20 minutes. Save the stock.',
      'Broil the chicken for 10 to 12 minutes until browned and 165°F in the thickest part.',
      'Blend the tomatoes, tatashe, half the second onion and the scotch bonnets. Boil in a pot for 15 minutes to reduce.',
      'Heat the oil in a heavy pot. Slice the rest of the onion and fry for 3 minutes, then fry the tomato paste for 2 minutes.',
      'Add the pepper mix and fry for 12 to 15 minutes until the oil rises.',
      'Add 1 cup of stock, the remaining stock cube and the chicken. Simmer for 10 minutes.',
      'Meanwhile cut the ends off the plantains and slit the skins. Boil in the 8 cups water with the remaining salt for 20 minutes, then peel.',
      'Serve one plantain per person with plenty of stew. No sugar goes in the stew, and Daddy keeps to 1 finger.']},

  /* ---------- Late plate ---------- */
  'eggs-cucumber': {time:'15 min', serves:'1',
    ing:['2 eggs','1/2 large cucumber','1 pinch salt','1 pinch black pepper','3 cups water'],
    steps:['Bring the water to a boil in a small pot and lower in the eggs with a spoon.',
      'Boil for 10 minutes.',
      'Move the eggs to cold water for 5 minutes, then peel.',
      'Wash the cucumber and slice it into thick rounds.',
      'Halve the eggs, sprinkle with the salt and pepper, and serve with the cucumber. Boiled eggs keep in the fridge for up to 5 days.']},

  'nuts-gardenegg': {time:'5 min', serves:'1',
    ing:['1/4 cup unsalted roasted groundnuts (one small handful)','3 garden eggs','1 pinch salt'],
    steps:['Wash the garden eggs under cold water and pat them dry.',
      'Trim off the stems and cut each one into quarters.',
      'Measure the groundnuts into a small bowl, so the portion stays at one small handful.',
      'Sprinkle a little salt over the garden eggs if you like.',
      'Serve together. Eat a piece of garden egg with a few nuts each time, and take it slowly.']},

  'soup-only': {time:'10 min', serves:'1',
    ing:['1 1/2 cups of tonight\'s soup, set aside before serving dinner','2 to 3 extra pieces of meat or fish from the pot','1/2 cup chopped ugu or spinach (optional)','2 tbsp water, if needed'],
    steps:['Before dinner goes to the table, ladle a bowl of soup into a container with extra meat or fish.',
      'Cool it, cover it and put it in the fridge if the late plate is more than 2 hours away.',
      'When ready to eat, pour it into a small pot and heat gently, adding the water if it has thickened.',
      'Stir in the ugu or spinach if using and bring back to a full simmer, until steaming hot throughout.',
      'Pour into a bowl and eat on its own with a spoon. No swallow needed.']},

  'suya-salad': {time:'35 min', serves:'2',
    ing:['12 oz beef sirloin or flank, in one piece','2 tbsp suya spice (yaji)','1 tbsp vegetable oil','1 small onion, thinly sliced','2 medium tomatoes, sliced','2 cups shredded cabbage','1 tsp lemon juice','1/4 tsp salt'],
    steps:['Put the beef in the freezer for 15 minutes to firm it up, then cut it into very thin strips across the grain.',
      'Toss the beef with the oil, salt and most of the yaji. Leave for 10 minutes.',
      'Thread the strips onto skewers (soak wooden ones first) or lay them flat on a rack over a foil-lined tray.',
      'Broil close to the heat for 3 to 4 minutes on each side until browned and sizzling.',
      'Toss the onion, tomatoes and cabbage with the lemon juice.',
      'Sprinkle the remaining yaji over the hot beef and serve on the salad. Skip the bread.']},

  'yoghurt-tiger': {time:'5 min + 2 hr soak', serves:'1',
    ing:['3/4 cup plain unsweetened yoghurt','2 tbsp dried tiger nuts','1 cup water for soaking','1/4 tsp ground cinnamon (optional)'],
    steps:['Soak the tiger nuts in the water for at least 2 hours, or overnight in the fridge, so they soften.',
      'Drain and rinse them, then chop them roughly.',
      'Check the yoghurt label: it should say no added sugar.',
      'Spoon the yoghurt into a small bowl and scatter the tiger nuts on top.',
      'Dust with cinnamon if you like and eat straight away.']},

  /* ---------- Yoruba home dishes ---------- */
  'abula': {time:'2 hr 15 min + overnight soak', serves:'6',
    ing:['3 cups elubo (yam flour)','6 cups water for the amala','1 lb ewedu leaves, fresh or frozen','2 cups water for the ewedu','2 cups dried honey beans or black-eyed peas','8 cups water for the beans','2 tbsp iru (locust beans)','2 lb assorted meat (beef, shaki, ponmo)','6 cups water for the meat','1/2 cup palm oil','3 tbsp ground crayfish','5 tatashe (or red bell peppers)','2 scotch bonnet peppers','1 large onion','2 stock cubes','1 1/2 tsp salt'],
    steps:['The night before, soak the beans for 10 minutes, rub off the skins, rinse them away, then cover with fresh water and refrigerate overnight.',
      'For the gbegiri, boil the peeled beans in the 8 cups water, hard for 10 minutes, then simmer for 50 to 60 minutes until they fall apart. Mash smooth, stir in 3 tablespoons of palm oil, 2 tablespoons of crayfish and 1/2 teaspoon salt, and simmer for 10 minutes.',
      'Boil the meat with half the onion, the stock cubes, 1/2 teaspoon salt and the 6 cups water for 50 to 60 minutes until tender. Save 1 cup of stock.',
      'Blend the tatashe, scotch bonnets and remaining onion. Boil in a dry pot for 10 minutes to reduce.',
      'Heat the rest of the palm oil and fry the pepper mix with 1 tablespoon of iru for 15 minutes until the oil rises. Add the meat and saved stock and simmer for 10 minutes.',
      'For the ewedu, boil the 2 cups water, add the leaves and cook for 5 minutes. Pulse in a blender a few times, or whisk with an ijabe, until fine but not foamy.',
      'Return the ewedu to the pot with the remaining iru, crayfish and salt, and warm for 2 minutes.',
      'For the amala, bring the 6 cups water to a boil, sprinkle in the elubo and stir fast with a wooden spoon until smooth and stretchy. Cover on low for 2 minutes and stir again.',
      'Serve the amala with ewedu and gbegiri side by side, with the meat stew on top.']},

  'plantain-amala': {time:'1 hr 20 min', serves:'6',
    ing:['6 large unripe (green) plantains','1 cup water for blending','1 lb ewedu leaves, fresh or frozen','2 cups water for the ewedu','2 tbsp iru (locust beans)','2 lb assorted meat (beef, shaki, ponmo)','6 cups water for the meat','1/3 cup palm oil','4 tatashe (or red bell peppers)','2 scotch bonnet peppers','1 large onion','2 tbsp ground crayfish','2 stock cubes','1 tsp salt'],
    steps:['Boil the meat with half the onion, the stock cubes, half the salt and the 6 cups water for 50 to 60 minutes until tender. Save 1 cup of the stock.',
      'Blend the tatashe, scotch bonnets and remaining onion. Boil in a dry pot for 10 minutes to reduce.',
      'Heat the palm oil and fry the pepper mix with 1 tablespoon of iru for 12 to 15 minutes until the oil rises. Add the meat and saved stock and simmer for 10 minutes.',
      'Boil the 2 cups water, add the ewedu leaves and cook for 5 minutes. Pulse a few times in a blender until fine.',
      'Return the ewedu to the pot with the remaining iru, the crayfish and remaining salt, and warm for 2 minutes.',
      'Peel the plantains, cut into chunks and blend with the 1 cup water until completely smooth.',
      'Pour into a heavy pot and stir constantly over medium heat for 12 to 15 minutes, until it darkens and becomes a thick, smooth dough. Add a splash of water, cover for 3 minutes and stir again.',
      'Shape into balls with a wet spoon and serve with the ewedu and stew. Daddy keeps his amala fist-size.']},

  'ewa-agoyin': {time:'2 hr + overnight soak', serves:'6',
    ing:['3 cups dried honey beans or black-eyed peas','12 cups water','1 1/2 tsp salt','1/2 cup palm oil','4 tatashe (or red bell peppers)','2 scotch bonnet peppers','3 large onions','1 stock cube','3 unripe (green) plantains (for Daddy and anyone who wants it)','6 cups water for the plantains'],
    steps:['The night before, cover the beans with plenty of water and soak. Drain and rinse them in the morning.',
      'Boil the beans in the 12 cups water, hard for 10 minutes, then simmer for 1 hour 15 minutes until very soft. Top up with hot water as needed.',
      'Add 1 teaspoon salt and mash well with a wooden spoon or potato masher until smooth. Cook off any spare water for 5 minutes.',
      'Blend the tatashe and scotch bonnets with one onion, then simmer in a dry pot for 15 minutes until thick and almost dry.',
      'Slice the other 2 onions. Heat the palm oil in a heavy pot on medium-low and fry them gently for 15 to 20 minutes, until very dark brown but not burnt.',
      'Stir in the reduced pepper, stock cube and remaining salt. Fry on low for 20 minutes, stirring often, until the sauce is deep and dark.',
      'Boil the plantains in their skins in the 6 cups water for 20 minutes, then peel.',
      'Spoon the beans into bowls and top with the sauce. Daddy has his with boiled plantain instead of bread, one finger only.']},

  'ikokore': {time:'1 hr', serves:'6',
    ing:['3 lb water yam (isu ewura)','1/2 cup palm oil','3 tbsp ground crayfish','1 lb smoked or dried fish, cleaned and flaked in large pieces','1 tbsp iru (locust beans)','3 scotch bonnet peppers','2 tatashe (or red bell peppers)','2 medium onions','1 stock cube','1 1/2 tsp salt','5 cups water'],
    steps:['Peel the water yam and grate it finely into a bowl, or blend with very little water. Stir in 1/2 teaspoon salt.',
      'Blend the scotch bonnets, tatashe and one onion until smooth. Slice the other onion.',
      'Heat the palm oil in a wide pot and fry the sliced onion and iru for 2 minutes.',
      'Pour in the blended pepper and fry for 8 minutes.',
      'Add the water, crayfish, stock cube and remaining salt, and bring to a boil.',
      'Using two spoons, drop small balls of grated yam into the boiling sauce. Do not stir.',
      'Lay the fish on top, cover and simmer on low for 25 to 30 minutes. Shake the pot gently now and then instead of stirring.',
      'It is ready when the balls are firm and the sauce is thick. Give one gentle stir and serve hot.']},

  'ila-alasepo': {time:'1 hr 15 min', serves:'6',
    ing:['1 1/2 lb fresh okra, finely chopped','1 1/2 lb assorted meat (beef, shaki, ponmo)','1 lb fresh or smoked fish, cut into pieces','3 tbsp ground crayfish','2 tbsp iru (locust beans)','1/3 cup palm oil','4 tatashe (or red bell peppers)','2 scotch bonnet peppers','1 large onion','2 stock cubes','1 tsp salt','6 cups water for the meat','6 large unripe (green) plantains for plantain amala','1 cup water for blending'],
    steps:['Boil the meat with half the onion, the stock cubes, salt and the 6 cups water for 45 to 50 minutes until tender.',
      'Add the fish and simmer for 8 minutes until it flakes. There should be about 3 cups of stock in the pot.',
      'Blend the tatashe, scotch bonnets and remaining onion until coarse.',
      'Heat the palm oil in a wide pot, fry the iru for 1 minute, then add the pepper mix and fry for 10 minutes until the oil rises.',
      'Add the meat, fish, stock and crayfish, and simmer for 5 minutes.',
      'Stir in the okra and cook on medium, uncovered, for 3 to 4 minutes, until bright green and stretchy. Turn off the heat.',
      'For the plantain amala, peel and blend the plantains with the 1 cup water until smooth, then stir in a heavy pot over medium heat for 12 to 15 minutes until a thick, smooth dough forms.',
      'Serve the soup with the amala. Daddy keeps his fist-size.']},

  'ekuru': {time:'1 hr 15 min + overnight soak', serves:'2',
    ing:['1 cup dried honey beans or black-eyed peas','1/2 cup water for blending','1/4 tsp salt','2 tatashe (or 1 red bell pepper)','1 scotch bonnet pepper','1 medium onion','2 tbsp palm oil','2 tsp iru (locust beans)','1/4 stock cube'],
    steps:['The night before, soak the beans for 10 minutes, rub off the skins, rinse them away, then cover with fresh water and refrigerate overnight.',
      'Drain the beans and blend with the water until very smooth. Do not add onions or pepper; ekuru stays plain and white.',
      'Whisk the batter hard for 3 to 4 minutes until pale and fluffy, then stir in the salt.',
      'Spoon into 4 greased ramekins or foil cups and cover with foil. Steam on a rack over simmering water, covered, for 40 to 45 minutes until firm and a knife comes out clean.',
      'Meanwhile blend the tatashe, scotch bonnet and half the onion until coarse, and boil in a dry pot for 8 minutes to reduce.',
      'Heat the palm oil. Slice the remaining onion and fry for 2 minutes with the iru.',
      'Add the reduced pepper and stock cube and fry for 10 to 12 minutes until thick and the oil rises.',
      'Break up the ekuru into bowls and spoon the warm sauce over it.']},

  'ata-dindin-plantain': {time:'1 hr 30 min', serves:'6',
    ing:['6 tatashe (or red bell peppers)','4 medium tomatoes','3 scotch bonnet peppers','2 large onions','1/2 cup palm oil','2 lb assorted meat (beef, shaki, ponmo)','1 tbsp iru (locust beans)','2 stock cubes','1 tsp salt','6 cups water for the meat','6 unripe (green) plantains','8 cups water for the plantains'],
    steps:['Boil the meat with one sliced onion, the stock cubes, half the salt and the 6 cups water for 50 to 60 minutes until tender. Save 1/2 cup of the stock.',
      'Blend the tatashe, tomatoes and scotch bonnets until coarse. Pour into a pot and boil for 15 minutes, until nearly dry.',
      'Heat the palm oil in a heavy pot. Slice the second onion and fry for 3 minutes, then add the iru and fry for 1 minute.',
      'Add the reduced pepper and fry for 20 minutes, stirring often, until the stew is deep red and the oil sits on top.',
      'Add the meat and saved stock and fry for 10 minutes more.',
      'Cut the ends off the plantains and slit the skins. Boil in the 8 cups water with the remaining salt for 20 minutes, then peel.',
      'Serve one plantain per person with a generous spoon of stew and meat. Daddy has one finger and fills up on the meat.']},

  'boli-epa': {time:'35 min', serves:'4',
    ing:['4 ripe plantains','1 cup roasted groundnuts','1 tbsp vegetable oil','1/4 tsp salt'],
    steps:['Heat the oven to 400°F, or light the grill.',
      'Peel the plantains and leave them whole. Brush lightly with the oil and sprinkle with the salt.',
      'Lay them on a lined tray and roast for 25 to 30 minutes, turning twice, until browned in spots and soft inside.',
      'Cool for 5 minutes, then cut each plantain into thick slices.',
      'Divide the groundnuts into small portions and serve beside the plantain.',
      'For the lunchbox, cool fully and pack the nuts separately. Check first that the school allows nuts.']},

  /* ---------- Diabetic breakfast poster ---------- */
  'db-oatmeal': {time:'35 min', serves:'1',
    ing:['1/3 cup steel-cut oats','1 1/4 cups water','1/2 cup mixed berries','1 tbsp chia seeds','2 tbsp chopped mixed nuts','1 pinch salt'],
    steps:['Bring the water and salt to a boil in a small pot.',
      'Stir in the steel-cut oats and lower the heat.',
      'Simmer for 25 to 30 minutes, stirring now and then, until the oats are tender and creamy.',
      'Stir in the chia seeds and leave for 2 minutes to thicken.',
      'Spoon into a bowl, about 1 cup cooked, and top with the berries and nuts. Add no sugar.']},

  'db-avocado-toast': {time:'10 min', serves:'1',
    ing:['1 slice whole grain bread','1/2 ripe avocado','1 egg','5 cherry tomatoes, halved','1 tsp vegetable oil','1 pinch salt','1 pinch black pepper'],
    steps:['Toast the bread until golden.',
      'Scoop the avocado into a bowl and mash with a fork, adding the salt and pepper.',
      'Heat the oil in a small pan and fry the egg for 3 minutes, until the white and yolk are set.',
      'Spread the avocado over the toast.',
      'Top with the egg and tomatoes. One slice is the full portion.']},

  'db-parfait': {time:'5 min', serves:'1',
    ing:['3/4 cup plain low-fat Greek yogurt','1/2 cup mixed berries','2 tbsp chopped mixed nuts','1 tbsp ground flaxseeds'],
    steps:['Rinse the berries and pat dry. Cut any large ones in half.',
      'Stir the flaxseeds into the yogurt.',
      'Spoon half the yogurt into a glass or small jar and add half the berries.',
      'Add the rest of the yogurt and the remaining berries.',
      'Top with the nuts. If packing for later, keep the nuts in a separate small bag so they stay crunchy.']},

  'db-veggie-omelet': {time:'10 min', serves:'1',
    ing:['4 egg whites','1 cup fresh spinach, chopped','1/4 green bell pepper, diced','3 mushrooms, sliced','1 tsp vegetable oil','1 pinch salt','1 pinch black pepper'],
    steps:['Heat the oil in a nonstick pan over medium heat.',
      'Fry the mushrooms and green pepper for 3 minutes until soft.',
      'Add the spinach and stir for 1 minute until wilted. Tip onto a plate.',
      'Whisk the egg whites with the salt and pepper until foamy, and pour into the pan.',
      'Cook for 2 minutes until nearly set, spoon the vegetables over half, and fold it over. Cook 1 more minute until fully set.']},

  'db-green-smoothie': {time:'5 min', serves:'1',
    ing:['1 cup fresh spinach','1/2 cucumber, chopped','1 scoop unsweetened protein powder','1 cup unsweetened almond milk','1 tbsp ground flaxseeds','3 ice cubes'],
    steps:['Rinse the spinach and cucumber.',
      'Pour the almond milk into the blender first.',
      'Add the spinach, cucumber, protein powder and flaxseeds.',
      'Add the ice and blend for 1 minute until completely smooth.',
      'Pour into a glass and drink straight away. Add no honey or fruit juice.']},

  'db-cottage-bowl': {time:'5 min', serves:'1',
    ing:['3/4 cup low-fat cottage cheese','1/4 cup fresh pineapple, cut into small pieces','2 tbsp chopped walnuts'],
    steps:['Spoon the cottage cheese into a small bowl.',
      'Cut the pineapple into small pieces and measure out 1/4 cup. If using canned, pick pineapple in juice, not syrup, and drain well.',
      'Scatter the pineapple over the cottage cheese.',
      'Sprinkle the walnuts on top.',
      'Eat straight away, or cover and keep cold until you are ready.']},

  'db-chia-pudding': {time:'5 min + overnight chill', serves:'1',
    ing:['3 tbsp chia seeds','3/4 cup unsweetened almond milk','1 tbsp unsweetened cocoa powder','1/4 cup mixed berries'],
    steps:['Whisk the cocoa powder into a little of the almond milk in a jar until there are no lumps.',
      'Add the rest of the almond milk and the chia seeds and whisk well.',
      'Leave for 10 minutes, then stir again so the seeds do not clump.',
      'Cover and refrigerate overnight, or for at least 4 hours.',
      'Stir once more in the morning and top with the berries. Add no sugar.']},

  'db-pancakes': {time:'15 min', serves:'1',
    ing:['1/2 cup rolled oats','1 egg','1/2 small banana','1/4 cup blueberries','2 tbsp water','1/2 tsp baking powder','1 tsp vegetable oil'],
    steps:['Put the oats, egg, banana, water and baking powder in a blender. Blend until smooth.',
      'Let the batter rest for 3 minutes so it thickens.',
      'Heat the oil in a nonstick pan over medium-low heat.',
      'Pour in the batter to make two small pancakes and dot with half the blueberries.',
      'Cook for 2 to 3 minutes until bubbles form, then flip and cook for 2 minutes until set.',
      'Serve with the remaining blueberries. Use no syrup.']},

  'db-tofu-scramble': {time:'15 min', serves:'1',
    ing:['7 oz firm tofu (half a block)','1/2 green bell pepper, diced','1 cup fresh spinach','1/4 tsp ground turmeric','1 slice whole grain bread','2 tsp vegetable oil','1 pinch salt','1 pinch black pepper'],
    steps:['Press the tofu between paper towels for a few minutes to remove water, then crumble it with a fork.',
      'Heat the oil in a nonstick pan and fry the green pepper for 3 minutes.',
      'Add the tofu, turmeric, salt and black pepper. Cook for 5 minutes, stirring, until hot and lightly golden.',
      'Stir in the spinach and cook for 1 minute until wilted.',
      'Toast the bread and serve the scramble on top. One slice is enough.']},

  'db-overnight-oats': {time:'5 min + overnight chill', serves:'1',
    ing:['1/2 cup rolled oats','3/4 cup unsweetened almond milk','1/2 cup mixed berries','2 tbsp chopped mixed nuts','1/2 tsp ground cinnamon'],
    steps:['Put the oats and cinnamon in a jar with a lid.',
      'Pour in the almond milk and stir well.',
      'Add the berries on top, close the lid and refrigerate overnight.',
      'In the morning, stir and add a splash of almond milk if it is too thick.',
      'Top with the nuts. Take it straight from the fridge to work and keep it cold until you eat.']},

  'db-smoothie-bowl': {time:'5 min', serves:'1',
    ing:['1 cup frozen mixed berries','1/2 cup plain low-fat Greek yogurt','1 tbsp chia seeds','1 tbsp ground flaxseeds','2 tbsp water'],
    steps:['Take the berries from the freezer and leave them for 3 minutes to soften slightly. Keep back a few for the top.',
      'Put the berries, yogurt, flaxseeds and water in the blender.',
      'Blend until thick and smooth, scraping down the sides as needed.',
      'Spoon into a bowl. It should be thick enough to eat with a spoon.',
      'Top with the chia seeds and saved berries, and eat slowly.']},

  'db-nut-muffin': {time:'5 min', serves:'1',
    ing:['1 whole grain English muffin','2 tbsp unsweetened almond butter','3 strawberries, sliced'],
    steps:['Split the English muffin in half with a fork.',
      'Toast both halves until golden.',
      'Wash the strawberries, remove the green tops and slice them.',
      'Spread 1 tablespoon of almond butter on each half.',
      'Lay the strawberry slices on top and serve.']},

  'db-egg-plate': {time:'15 min', serves:'1',
    ing:['2 eggs','1/2 cucumber, sliced','6 cherry tomatoes','2 tbsp hummus','1 pinch black pepper','3 cups water'],
    steps:['Bring the water to a boil, lower in the eggs and boil for 10 minutes. Skip this step if you have eggs boiled ahead.',
      'Cool the eggs in cold water for 5 minutes, then peel and halve.',
      'Wash the cucumber and tomatoes and slice the cucumber.',
      'Spoon the hummus onto a plate.',
      'Arrange the eggs and vegetables around it, and finish with the black pepper.']},

  'db-fruit-nut-bowl': {time:'5 min', serves:'1',
    ing:['1/2 cup mixed berries','1/2 small apple, diced','2 tbsp almonds','1 pinch ground cinnamon'],
    steps:['Rinse the berries and pat dry.',
      'Wash the apple, core it and dice half. Leave the skin on.',
      'Roughly chop the almonds.',
      'Put the fruit in one small bowl and top with the almonds.',
      'Dust with the cinnamon and eat the nuts along with the fruit, so the sugar comes through slowly.']},

  'db-turkey-wrap': {time:'5 min', serves:'1',
    ing:['1 whole grain wrap','3 oz low-sodium sliced turkey','1 cup fresh spinach','2 tbsp hummus'],
    steps:['Warm the wrap in a dry pan for 20 seconds on each side so it folds easily.',
      'Spread the hummus over the wrap, leaving a small border.',
      'Lay the turkey down the middle and pile on the spinach.',
      'Fold in the two sides, then roll it up tightly from the bottom.',
      'Cut in half on an angle. If it is going to work, wrap it in foil and keep it cold.']},

  'db-apple-yogurt': {time:'5 min', serves:'1',
    ing:['3/4 cup plain low-fat Greek yogurt','1/2 small apple, diced','1/2 tsp ground cinnamon','2 tbsp chopped walnuts'],
    steps:['Wash the apple, core it and dice half. Leave the skin on.',
      'Spoon the yogurt into a bowl.',
      'Stir in half the cinnamon.',
      'Top with the apple and walnuts.',
      'Dust with the remaining cinnamon and serve. Add no honey.']},

  /* ---------- Extra meals ---------- */
  'garden-egg-stew': {time:'40 min', serves:'2',
    ing:['6 garden eggs','2 eggs','2 medium tomatoes','1 tatashe (or 1/2 red bell pepper)','1 medium onion','1/2 scotch bonnet pepper','2 tbsp palm oil','1 tbsp ground crayfish','1/2 stock cube','1/4 tsp salt','2 unripe (green) plantains','4 cups water for the plantains'],
    steps:['Cut the ends off the plantains, slit the skins and boil in the water for 20 minutes. Peel while warm.',
      'Wash the garden eggs and steam or boil them in a little water for 10 minutes until soft. Peel off the skins if you like, then mash with a fork.',
      'Blend the tomatoes, tatashe and scotch bonnet until coarse. Slice the onion.',
      'Heat the palm oil in a skillet and fry the onion for 2 minutes. Add the blended mix and fry for 10 minutes until thick.',
      'Stir in the mashed garden eggs, crayfish, stock cube and salt. Cook for 5 minutes.',
      'Beat the eggs, pour them in and stir gently for 2 to 3 minutes until set.',
      'Serve one finger of plantain per person with plenty of stew.']},

  'ojojo': {time:'30 min', serves:'4',
    ing:['2 lb water yam (or regular white yam)','1 medium onion, finely chopped','1 scotch bonnet pepper, finely chopped','1/2 tsp salt','3 cups vegetable oil for frying'],
    steps:['Peel the yam and rinse it. Grate it finely into a bowl.',
      'Stir in the onion, scotch bonnet and salt. It should be a soft, thick batter.',
      'Heat the oil in a deep pot to 350°F.',
      'Drop in tablespoons of batter, a few at a time.',
      'Fry for 4 to 5 minutes, turning, until golden on all sides and cooked through.',
      'Drain on paper towels and serve warm, or cool fully before packing. Daddy has 2 pieces at most, with eggs.']},

  'scotch-eggs': {time:'45 min', serves:'4',
    ing:['4 eggs, plus 1 beaten for coating','1 lb minced beef or sausage meat','1 small onion, grated','1/2 cup all-purpose flour','1 cup breadcrumbs','1/2 tsp dried thyme','1/2 tsp curry powder','1/2 stock cube, crushed','3 cups vegetable oil for frying'],
    steps:['Boil 4 eggs for 9 minutes, cool them in cold water and peel. You can do this the night before.',
      'Mix the meat with the onion, thyme, curry and stock cube. Divide into 4 equal balls.',
      'Dust each egg with flour. Flatten a meatball in your palm and wrap it around the egg, sealing the edges.',
      'Roll each one in flour, then the beaten egg, then the breadcrumbs.',
      'Heat the oil to 325°F. Fry two at a time for 7 to 8 minutes, turning, until deep golden and the meat reaches 160°F.',
      'Drain on paper towels and cool, then cut in half. Daddy bakes his at 400°F for 25 minutes instead.']},

  'coconut-rice': {time:'1 hr 15 min', serves:'6',
    ing:['3 cups long-grain parboiled rice','2 cans (13.5 oz each) coconut milk','3 lb chicken pieces','3 tatashe (or red bell peppers)','2 large onions','1 scotch bonnet pepper','3 tbsp ground crayfish','2 stock cubes','1/4 cup vegetable oil','1 tsp curry powder','1 tsp dried thyme','1 tsp salt','4 cups water'],
    steps:['Boil the chicken with one sliced onion, the thyme, 1 stock cube, half the salt and the water for 20 minutes. Save the stock.',
      'Bake the chicken at 425°F for 15 minutes until golden and 165°F in the thickest part.',
      'Blend the tatashe, scotch bonnet and half the second onion until smooth.',
      'Heat the oil in a heavy pot. Slice the rest of the onion and fry for 2 minutes, then add the blended mix and fry for 8 to 10 minutes until thick.',
      'Add the coconut milk, 1 1/2 cups of the chicken stock, crayfish, curry, remaining stock cube and salt. Bring to a boil.',
      'Rinse the rice and stir it in. The liquid should sit just level with the rice.',
      'Cover with foil and a tight lid and cook on low for 25 to 30 minutes, stirring once, until tender.',
      'Fluff with a fork and serve with the chicken. Cool before packing a lunchbox and add an ice pack.']},

  'chicken-shawarma': {time:'40 min + overnight marinating', serves:'4',
    ing:['1 1/2 lb boneless chicken thighs, cut into thin strips','4 large tortilla wraps','2 cups shredded cabbage','1 medium carrot, grated','1/2 cucumber, cut into thin sticks','1/3 cup mayonnaise','4 sausages','1 tbsp vegetable oil','1 tsp curry powder','1 tsp paprika','1/2 tsp garlic powder','1/2 tsp salt'],
    steps:['Toss the chicken with the curry, paprika, garlic powder, salt and oil. Cover and refrigerate overnight, or for at least 30 minutes.',
      'Cook the chicken in a hot skillet for 8 to 10 minutes, in two batches, until browned and 165°F.',
      'Cook the sausages in the same pan for 10 minutes until browned and cooked through to 160°F, then slice them lengthwise.',
      'Mix the cabbage and carrot with half the mayonnaise.',
      'Spread the rest of the mayonnaise over the tortillas. Add the slaw, cucumber, chicken and sausage down the middle.',
      'Fold in the bottom, roll up tightly and toast in a dry pan for 1 minute on each side.',
      'Cool, wrap in foil and pack with an ice pack, because of the mayonnaise.']},

  'unripe-plantain-porridge': {time:'50 min', serves:'6',
    ing:['5 large unripe (green) plantains','1/3 cup palm oil','3 tbsp ground crayfish','1 lb smoked or fresh fish, cleaned and cut into pieces','3 cups ugu leaves, chopped','2 medium onions, one blended and one sliced','2 scotch bonnet peppers, blended','1 stock cube','1 tsp salt','6 cups water'],
    steps:['Peel the plantains and cut into small cubes.',
      'Put them in a pot with the water, blended onion and scotch bonnets, stock cube and salt. Boil for 15 minutes.',
      'Add the palm oil, crayfish and sliced onion, and stir well.',
      'Lay the fish on top and simmer on low for 10 to 12 minutes, until the plantain is tender and the fish flakes.',
      'Mash some of the plantain against the side of the pot so the porridge thickens.',
      'Stir in the ugu and cook for 2 minutes.',
      'Serve hot. Daddy has about 1 cup with extra ugu and fish.']},

  'cauli-jollof': {time:'40 min', serves:'2',
    ing:['1 medium head cauliflower','2 boneless chicken thighs','2 medium tomatoes','2 tatashe (or 1 red bell pepper)','1 medium onion','1/2 scotch bonnet pepper','1 tbsp tomato paste','2 tbsp vegetable oil','1 tsp curry powder','1/2 tsp dried thyme','1/2 stock cube, crushed','1/4 tsp salt'],
    steps:['Rub the chicken with half the curry and thyme and a pinch of salt. Bake at 425°F for 20 to 25 minutes until 165°F in the thickest part.',
      'Pulse the cauliflower in a food processor until it looks like rice, or grate it on a box grater.',
      'Blend the tomatoes, tatashe, half the onion and scotch bonnet. Boil in a pot for 8 minutes until reduced.',
      'Heat the oil in a wide pan. Slice the rest of the onion and fry for 2 minutes, then fry the tomato paste for 2 minutes.',
      'Add the reduced pepper mix, remaining curry, thyme, stock cube and salt. Fry for 8 minutes until the oil rises.',
      'Stir in the cauliflower and cook on medium-high for 5 to 6 minutes, uncovered, until tender and coated.',
      'Serve with the chicken.']},

  'peppered-croaker': {time:'35 min', serves:'2',
    ing:['2 small whole croaker or tilapia, cleaned','2 tatashe (or 1 red bell pepper)','1 medium onion','1 scotch bonnet pepper','2 tbsp vegetable oil','1/2 tsp dried thyme','1/2 stock cube, crushed','1/4 tsp salt','1 cucumber, sliced, to serve'],
    steps:['Cut 3 slits on each side of the fish. Rub with 1 tablespoon of oil, the thyme and salt.',
      'Broil on a lined tray for 7 to 8 minutes per side, until the skin is crisp and the flesh flakes at 145°F.',
      'Blend the tatashe, scotch bonnet and half the onion until coarse. Slice the rest of the onion.',
      'Heat the remaining oil in a skillet and fry the sliced onion for 2 minutes.',
      'Add the blended pepper and stock cube and fry for 8 to 10 minutes until thick.',
      'Spoon the pepper sauce over the fish and serve with the cucumber.']},

  'asun': {time:'1 hr 15 min', serves:'2',
    ing:['1 lb goat meat, cut into small pieces (or 1 lb catfish steaks)','2 tatashe (or 1 red bell pepper)','2 scotch bonnet peppers','2 medium onions','1 stock cube','1 tbsp vegetable oil','1/2 tsp salt','3 cups water','1/2 cucumber, sliced, to serve'],
    steps:['Put the goat in a pot with one sliced onion, the stock cube, salt and water. Simmer for 40 to 45 minutes until tender, then drain, saving 1/4 cup of the stock.',
      'Spread the meat on a foil-lined tray and broil or grill for 8 to 10 minutes, turning once, until browned at the edges and smoky. If using catfish, skip the boiling and broil for 7 minutes per side.',
      'Coarsely blend the tatashe, scotch bonnets and half the second onion.',
      'Heat the oil in a wide pan and fry the pepper mix for 6 to 8 minutes until most of the water is gone.',
      'Add the meat and saved stock and toss on high heat for 3 minutes, until the pepper coats each piece.',
      'Slice the rest of the onion and scatter over the top. Serve a palm-size portion with the cucumber.']},

  'chicken-suya': {time:'35 min + overnight marinating', serves:'2',
    ing:['12 oz boneless chicken thighs, cut into strips','2 tbsp suya spice (yaji)','1 tbsp vegetable oil','1/4 tsp salt','1 small onion, thinly sliced','2 medium tomatoes, sliced','2 cups shredded cabbage','1 tsp lemon juice'],
    steps:['Toss the chicken with the oil, salt and most of the yaji. Cover and refrigerate overnight, or for at least 30 minutes.',
      'Thread onto skewers (soak wooden ones first) or spread on a rack over a foil-lined tray.',
      'Broil, grill or air-fry at 400°F for 12 to 15 minutes, turning once, until charred at the edges and 165°F.',
      'Toss the onion, tomatoes and cabbage with the lemon juice.',
      'Sprinkle the remaining yaji over the chicken.',
      'Serve on the cabbage salad, with no bread. For a lunchbox, cool first and add an ice pack.']},

  'afang-soup': {time:'1 hr 20 min', serves:'6',
    ing:['3 cups ground or finely shredded afang leaves (fresh or frozen)','1 lb waterleaf (or fresh spinach), chopped','1 cup cleaned periwinkle','2 lb assorted meat (beef, shaki, ponmo)','4 oz stockfish pieces','3 tbsp ground crayfish','1/2 cup palm oil','2 scotch bonnet peppers, chopped','1 large onion, sliced','2 stock cubes','1 tsp salt','5 cups water for the meat','3 cups garri for the family eba','5 cups water for the family eba','1/3 cup oat flour for Daddy\'s swallow','2/3 cup water for Daddy\'s swallow'],
    steps:['Soak the stockfish in hot water for 30 minutes, then boil it with the meat, onion, stock cubes, salt and the 5 cups water for 50 to 60 minutes until tender. About 1 1/2 cups of stock should remain.',
      'Add the periwinkle, crayfish and scotch bonnet, and simmer for 5 minutes.',
      'Add the waterleaf and cook for 5 minutes, until it softens and releases its water.',
      'Pour in the palm oil and simmer for 5 minutes.',
      'Stir in the afang leaves and cook on low for 5 to 7 minutes. The soup should be thick and dark green.',
      'For the eba, boil the 5 cups water, take off the heat and sprinkle in the garri. Leave for 1 minute, then turn hard with a wooden spoon until smooth.',
      'For Daddy, boil the 2/3 cup water, stir in the oat flour and turn for 3 to 4 minutes until firm. Keep it fist-size, or skip swallow altogether.']},

  'groundnut-soup': {time:'1 hr 20 min', serves:'6',
    ing:['2 cups roasted unsalted groundnuts','2 lb assorted meat (beef, shaki, ponmo)','4 oz stockfish pieces','3 tbsp ground crayfish','3 cups ugu leaves, chopped','4 tatashe (or red bell peppers)','2 scotch bonnet peppers','2 medium onions','2 stock cubes','1 tsp salt','8 cups water for the meat','1 cup water for blending','3 cups semolina or wheat flour for the family swallow','6 cups water for the family swallow','1/3 cup oat flour for Daddy\'s swallow','2/3 cup water for Daddy\'s swallow'],
    steps:['Soak the stockfish in hot water for 30 minutes, then boil it with the meat, one sliced onion, the stock cubes, salt and the 8 cups water for 50 to 60 minutes until tender. Keep all the stock.',
      'Blend the groundnuts with the 1 cup water until you have a smooth, thick paste.',
      'Blend the tatashe, scotch bonnets and second onion until smooth.',
      'Add the pepper mix to the meat pot and boil for 10 minutes.',
      'Whisk in the groundnut paste and crayfish. Simmer on low for 15 to 20 minutes, stirring often so it does not stick, until a little oil rises to the top.',
      'Stir in the ugu and cook for 3 minutes.',
      'For the swallow, boil the 6 cups water and sprinkle in the semolina or wheat flour, stirring all the time. Cook on low for 5 minutes, turning hard, until smooth and firm.',
      'For Daddy, boil the 2/3 cup water, stir in the oat flour and turn for 3 to 4 minutes until firm. Keep it small, or have the soup alone.']},
};
